local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();print('CURRENT',p:GetCurrentTimeline():GetName(),'RENDERING',p:IsRenderingInProgress());for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if t:GetName()=='v20 FINAL - 1.1x Michelle' then print('FINAL',t:GetEndFrame());for _,kind in ipairs({'video','audio'}) do for _,c in ipairs(t:GetItemListInTrack(kind,1)) do print(kind,c:GetStart(),c:GetEnd());dump(c:GetSpeed()) end end end end
